class Solution { public int maxPerformance(int n,int[] speed,int[] efficiency,int k){int[][] engineers=new int[n][2];for(int i=0;i<n;i++)engineers[i]=new int[]{efficiency[i],speed[i]};Arrays.sort(engineers,(a,b)->Integer.compare(b[0],a[0]));PriorityQueue<Integer> heap=new PriorityQueue<>();long sum=0,answer=0;for(int[] engineer:engineers){heap.offer(engineer[1]);sum+=engineer[1];if(heap.size()>k)sum-=heap.poll();answer=Math.max(answer,sum*engineer[0]);}return (int)(answer%1_000_000_007L);} }
